/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing -Vpotula
/// Controller class for customizing the customer statement as per AMEX proposal requirement.
/// </summary>
class METAMEXCustAccountStmtExtController extends CustAccountStatementExtController
{
    str             reportCompany;
    JournalId       journalId;
 
}

Method.Source:
protected void processParty(Query _query, DirPartyRecId _party, container _selectedCompanyList)
{
    super( _query,
          _party,
          [reportCompany]);
}

    /// <summary>
    /// Apply customer account & company range to base query
    /// </summary>
    public void updateBaseQuery(Query           _query,
                                CustAccount     _custAccount)
    {
        CustTable custTable;
        QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(CustTable));
        FormDataSource formDataSource;
        QueryBuildRange range;
        str rangeStr;

        _query.allowCrossCompany(true);
        _query.addCompanyRange(reportCompany);
        SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum)).value(_custAccount);
        if (this.parmArgs() && this.parmArgs().record() && this.parmArgs().record().TableId == tableNum(CustTable))
        {
            custTable = CustTable::findRecId(this.parmArgs().record().RecId);
            this.parmContract().parmPrintGiro(custTable.GiroTypeAccountStatement);
            rangeStr = queryValue(custTable.AccountNum);
            SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum)).value(rangeStr);
        }
    }

/// <summary>
/// Initialize default parameters
/// </summary>
/// <param name = "_args">Arguments to process statement.</param>
public void initParms(Args _args)
{
    this.parmArgs(_args);
    this.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::CustAccountStatement).getDefaultReportFormat());
    this.parmShowDialog(false);
    this.parmLoadFromSysLastValue(false);
}

    public str parmSelectedCompany(str _company = reportCompany)
    {
        reportCompany = _company;

        return reportCompany;
    }

public JournalId parmjournalId(JournalId _journalId = journalId)
{
    journalId = _journalId;
    
    return journalId;
}
